Object.assign(SNIP,{"l46tu": "class LoiRutTien : public runtime_error {   // kế thừa lớp ngoại lệ chuẩn\n    int thieu;\npublic:\n    LoiRutTien(int t) : runtime_error(\"Khong du tien\"), thieu(t) {}\n    int soThieu() const { return thieu; }\n};\nthrow LoiRutTien(50);                        // bắt được bằng catch (const LoiRutTien&),\n                                             // catch (const runtime_error&) hoặc catch (const exception&)", "l46cu": "double chia(double a, double b) {\n    if (b == 0) throw runtime_error(\"Chia cho 0\");   // ném: dừng hàm ngay, đi tìm catch\n    return a / b;\n}\ntry {\n    cout << chia(1, 0);          // ném ở trong chia(): dòng này không in gì\n} catch (const runtime_error& e) {\n    cout << \"Loi: \" << e.what(); // e.what(): thông điệp lúc ném\n}"});PRESET_NOTES["l46"]={"Ví dụ: ném và bắt ngoại lệ": "Lần gọi thứ hai ném ngoại lệ: chia() dừng ngay (không tới return), dòng in kết quả và dòng “khong chay” bị bỏ qua, chương trình nhảy thẳng vào catch. Sau catch, chương trình chạy tiếp bình thường.", "Ví dụ: gỡ ngăn xếp, hàm hủy vẫn chạy": "Ngoại lệ đi từ c lên b rồi lên main. Mỗi tầng bị bỏ dở được gỡ: “- c”, rồi “- b”, rồi biến trong khối try (“- trong try”) đều bị hủy TRƯỚC khi catch chạy. Biến m của main vẫn sống tới cuối main. catch (const exception&) bắt được invalid_argument vì exception là lớp cha của nó.", "Ví dụ: ngoại lệ của thư viện chuẩn": "v.at(5) kiểm tra chỉ số và ném out_of_range (v[5] thì không kiểm tra gì). stoi ném invalid_argument khi chuỗi không bắt đầu bằng số, ném out_of_range khi số vượt phạm vi int. Mỗi lần lặp có try riêng nên một chuỗi sai không làm dừng cả vòng lặp.", "Ví dụ: lớp ngoại lệ tự viết": "LoiRutTien kế thừa runtime_error nên có sẵn what(), và mang thêm thông tin riêng (số tiền thiếu). catch LoiRutTien đứng trước catch exception: rút 200 vào catch thứ nhất, rút −5 (invalid_argument) vào catch thứ hai.", "Ví dụ: catch (...) và throw;": "xuLy bắt logic_error để ghi nhận, rồi throw; ném lại đúng ngoại lệ đó cho main xử lý tiếp. throw 42 ném một int: không phải exception nên catch của xuLy bỏ qua, và chỉ catch (...) của main bắt được.", "Ví dụ: RAII giữ cho không rò rỉ": "Khi tinh(5) ném, tam (unique_ptr) và v (vector) bị hủy trong lúc gỡ ngăn xếp nên vùng nhớ heap được trả. Nếu tam là int* cấp bằng new và delete ở cuối hàm, ngoại lệ sẽ bỏ qua dòng delete và gây rò rỉ.", "Lỗi: không ai bắt ngoại lệ": "Không có try/catch nào: ngoại lệ đi lên tới hết main mà không ai bắt, C++ gọi terminate, in tên kiểu và what() rồi dừng chương trình (mã 134).", "Lỗi: bắt theo giá trị, catch lớp cha trước": "catch (exception e) chép ngoại lệ thành một exception thuần (mất phần LoiRieng) nên what() trả về \"std::exception\". Ở khối thứ hai, catch runtime_error đứng trước đã bắt cả LoiRieng, catch phía sau không bao giờ chạy. g++ cảnh báo cả hai chỗ."};EX_HINTS["l46"]=[["Đặt try bên trong vòng lặp để một chuỗi sai không làm dừng các chuỗi sau.", "Hai catch riêng cho invalid_argument và out_of_range."], ["Một catch (const exception& e) bắt được cả hai loại vì cả hai đều kế thừa exception.", "Ném xong thì du không bị trừ: dòng du -= x không chạy."], ["at() nhận size_t: chỉ số −1 đổi thành một số rất lớn, cũng ném out_of_range.", "Chỉ tăng dung sau khi in thành công (ngoại lệ bỏ qua dòng dung++)."]];
/* ===================== BÀI 46 · Ngoại lệ ===================== */
/* Bài 46 · Ngoại lệ
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P46=[{label:"Ví dụ: ném và bắt ngoại lệ",input:"",code:"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\ndouble chia(double a, double b) {\n    if (b == 0) {\n        throw runtime_error(\"Chia cho 0\");\n    }\n    return a / b;\n}\nint main() {\n    try {\n        cout << chia(6, 3) << \"\\n\";\n        cout << chia(1, 0) << \"\\n\";\n        cout << \"Dong nay khong chay\\n\";\n    } catch (const runtime_error& e) {\n        cout << \"Loi: \" << e.what() << \"\\n\";\n    }\n    cout << \"Chuong trinh chay tiep\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: gỡ ngăn xếp, hàm hủy vẫn chạy",input:"",code:"#include <iostream>\n#include <stdexcept>\n#include <string>\nusing namespace std;\n\nclass NhatKy {\n    string ten;\npublic:\n    NhatKy(string t) : ten(t) { cout << \"+ \" << ten << \"\\n\"; }\n    ~NhatKy() { cout << \"- \" << ten << \"\\n\"; }\n};\nvoid c() {\n    NhatKy k(\"c\");\n    throw invalid_argument(\"du lieu sai\");\n}\nvoid b() {\n    NhatKy k(\"b\");\n    c();\n    cout << \"khong in\\n\";\n}\nint main() {\n    NhatKy m(\"main\");\n    try {\n        NhatKy t(\"trong try\");\n        b();\n    } catch (const exception& e) {\n        cout << \"Bat duoc: \" << e.what() << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: ngoại lệ của thư viện chuẩn",input:"",code:"#include <iostream>\n#include <vector>\n#include <string>\n#include <stdexcept>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3};\n    try {\n        cout << v.at(5) << \"\\n\";\n    } catch (const out_of_range& e) {\n        cout << \"Ngoai pham vi: \" << e.what() << \"\\n\";\n    }\n    string ds[] = {\"42\", \"abc\", \"99999999999\"};\n    for (string s : ds) {\n        try {\n            cout << stoi(s) * 2 << \"\\n\";\n        } catch (const invalid_argument& e) {\n            cout << s << \" khong phai so\\n\";\n        } catch (const out_of_range& e) {\n            cout << s << \" qua lon cho int\\n\";\n        }\n    }\n    return 0;\n}"},{label:"Ví dụ: lớp ngoại lệ tự viết",input:"",code:"#include <iostream>\n#include <stdexcept>\n#include <string>\nusing namespace std;\n\nclass LoiRutTien : public runtime_error {\n    int thieu;\npublic:\n    LoiRutTien(int t) : runtime_error(\"Khong du tien\"), thieu(t) {}\n    int soThieu() const { return thieu; }\n};\nclass TaiKhoan {\n    int du;\npublic:\n    TaiKhoan(int d) : du(d) {}\n    void rut(int x) {\n        if (x <= 0) throw invalid_argument(\"So tien phai duong\");\n        if (x > du) throw LoiRutTien(x - du);\n        du -= x;\n    }\n    int soDu() const { return du; }\n};\nint main() {\n    TaiKhoan tk(100);\n    int ds[] = {30, -5, 200, 50};\n    for (int x : ds) {\n        try {\n            tk.rut(x);\n            cout << \"Rut \" << x << \", con \" << tk.soDu() << \"\\n\";\n        } catch (const LoiRutTien& e) {\n            cout << e.what() << \", thieu \" << e.soThieu() << \"\\n\";\n        } catch (const exception& e) {\n            cout << \"Loi: \" << e.what() << \"\\n\";\n        }\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: catch (...) và throw;",input:"",code:"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\nvoid xuLy(int loai) {\n    try {\n        if (loai == 1) throw logic_error(\"loi logic\");\n        if (loai == 2) throw 42;\n        cout << \"Binh thuong\\n\";\n    } catch (const exception& e) {\n        cout << \"Ghi nhan: \" << e.what() << \"\\n\";\n        throw;\n    }\n}\nint main() {\n    for (int i = 0; i < 3; i++) {\n        try {\n            xuLy(i);\n        } catch (const logic_error& e) {\n            cout << \"main xu ly: \" << e.what() << \"\\n\";\n        } catch (...) {\n            cout << \"Ngoai le la, khong biet kieu\\n\";\n        }\n    }\n    return 0;\n}"},{label:"Ví dụ: RAII giữ cho không rò rỉ",input:"",code:"#include <iostream>\n#include <stdexcept>\n#include <memory>\n#include <vector>\nusing namespace std;\n\nint tinh(int n) {\n    unique_ptr<int> tam = make_unique<int>(n * 10);\n    vector<int> v(n, 1);\n    if (n > 3) throw overflow_error(\"n qua lon\");\n    return *tam + v.size();\n}\nint main() {\n    try {\n        cout << tinh(2) << \"\\n\";\n        cout << tinh(5) << \"\\n\";\n    } catch (const exception& e) {\n        cout << e.what() << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: không ai bắt ngoại lệ",input:"",code:"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\nint layTuoi(int nam) {\n    if (nam > 2026) throw invalid_argument(\"Nam sinh o tuong lai\");\n    return 2026 - nam;\n}\nint main() {\n    cout << layTuoi(2000) << \"\\n\";\n    cout << layTuoi(2030) << \"\\n\";\n    cout << \"Ket thuc\\n\";\n    return 0;\n}"},{label:"Lỗi: bắt theo giá trị, catch lớp cha trước",input:"",code:"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\nclass LoiRieng : public runtime_error {\npublic:\n    LoiRieng() : runtime_error(\"loi rieng\") {}\n    const char* what() const noexcept override { return \"LoiRieng: chi tiet\"; }\n};\nint main() {\n    try {\n        throw LoiRieng();\n    } catch (exception e) {\n        cout << e.what() << \"\\n\";\n    }\n    try {\n        throw LoiRieng();\n    } catch (const runtime_error& e) {\n        cout << \"cha: \" << e.what() << \"\\n\";\n    } catch (const LoiRieng& e) {\n        cout << \"con\\n\";\n    }\n    return 0;\n}"}];
const sim46=makeSim2(document.getElementById("sim-l46"),{id:"s46",presets:P46});
makeEx2(document.getElementById("ex-l46"),sim46,[{t:"Đổi chuỗi thành số an toàn",d:"Nhập q rồi q chuỗi. Với mỗi chuỗi, đổi thành số nguyên bằng <code>stoi<\/code> trong khối try: thành công thì in gấp đôi số đó; nếu <code>stoi<\/code> ném <code>invalid_argument<\/code> in <code>Khong hop le<\/code>; nếu ném <code>out_of_range<\/code> in <code>Qua lon<\/code>. (<code>stoi<\/code> đọc phần số ở đầu chuỗi: \"12ab\" cho 12.)",tests:[{in:"4\n21\nabc\n12ab\n99999999999",out:"42\nKhong hop le\n24\nQua lon"},{in:"2\n-5\nx",out:"-10\nKhong hop le"}],start:"#include <iostream>\n#include <string>\n#include <stdexcept>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string s;\n        cin >> s;\n        // try { ... stoi(s) ... } catch (...) { ... }\n    }\n    return 0;\n}",need:/try[\s\S]*catch\s*\([^)]*invalid_argument[\s\S]*catch\s*\([^)]*out_of_range|try[\s\S]*catch\s*\([^)]*out_of_range[\s\S]*catch\s*\([^)]*invalid_argument/,needMsg:"Hãy dùng try và hai catch: invalid_argument, out_of_range."},{t:"Rút tiền có kiểm tra",d:"Viết <code>void rut(int&amp; du, int x)<\/code>: x ≤ 0 thì ném <code>invalid_argument(\"So tien khong hop le\")<\/code>; x &gt; du thì ném <code>runtime_error(\"Khong du tien\")<\/code>; còn lại trừ du. Nhập số dư ban đầu, q rồi q số tiền; với mỗi lần rút in <code>OK du_con_lai<\/code> hoặc nội dung <code>what()<\/code> của ngoại lệ.",tests:[{in:"100 4\n30\n-5\n200\n70",out:"OK 70\nSo tien khong hop le\nKhong du tien\nOK 0"},{in:"5 1\n5",out:"OK 0"}],start:"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\nvoid rut(int& du, int x) {\n    // throw ... khi không hợp lệ\n}\nint main() {\n    int du, q;\n    cin >> du >> q;\n    for (int i = 0; i < q; i++) {\n        int x;\n        cin >> x;\n        // try { rut(du, x); cout << \"OK \" << du << \"\\n\"; } catch ...\n    }\n    return 0;\n}",need:/throw[\s\S]*throw[\s\S]*try[\s\S]*catch/,needMsg:"Hàm rut phải ném ngoại lệ, main phải bắt bằng try/catch."},{t:"Truy cập vector an toàn",d:"Nhập n và n số, rồi q chỉ số. Với mỗi chỉ số i, in <code>v.at(i)<\/code>; nếu ném <code>out_of_range<\/code> thì in <code>Chi so i khong hop le<\/code>. Cuối cùng in số câu hỏi hợp lệ.",tests:[{in:"3\n5 6 7\n4\n0\n3\n-1\n2",out:"5\nChi so 3 khong hop le\nChi so -1 khong hop le\n7\n2"},{in:"1\n9\n1\n0",out:"9\n1"}],start:"#include <iostream>\n#include <vector>\n#include <stdexcept>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    int q, dung = 0;\n    cin >> q;\n    for (int k = 0; k < q; k++) {\n        int i;\n        cin >> i;\n        // try { cout << v.at(i) ... } catch (const out_of_range& e) { ... }\n    }\n    cout << dung << \"\\n\";\n    return 0;\n}",need:/\.at\s*\([\s\S]*catch\s*\([^)]*out_of_range/,needMsg:"Hãy dùng v.at(i) và catch out_of_range."}]);

makeQuiz("quiz46","score46",[{"q": "Sau khi <code>throw<\/code> trong một hàm được gọi từ khối try, điều gì xảy ra trước khi catch chạy?", "o": ["Không có gì, nhảy thẳng vào catch", "Các hàm bị bỏ dở được gỡ: biến cục bộ của chúng bị hủy (hàm hủy chạy)", "Chương trình dừng", "Hàm chạy tiếp tới return"], "a": 1, "e": "Gỡ ngăn xếp hủy mọi biến cục bộ trên đường đi, nên RAII bảo đảm không rò rỉ."}, {"q": "Nên bắt ngoại lệ chuẩn thế nào?", "o": ["catch (exception e)", "catch (const exception& e)", "catch (exception* e)", "catch (int e)"], "a": 1, "e": "Bắt theo tham chiếu const để không chép và không cắt mất phần lớp con."}, {"q": "Có <code>catch (const exception&amp;)<\/code> đứng TRƯỚC <code>catch (const out_of_range&amp;)<\/code>. Khi ném out_of_range:", "o": ["catch out_of_range chạy", "catch exception chạy, catch sau không bao giờ chạy", "Cả hai cùng chạy", "Lỗi biên dịch"], "a": 1, "e": "catch được xét từ trên xuống; exception là lớp cha nên khớp trước. Đặt lớp con trước lớp cha."}, {"q": "Ngoại lệ được ném mà không có catch nào khớp thì:", "o": ["Bị bỏ qua", "Chương trình gọi terminate và dừng", "Trả về 0", "Được in ra rồi chạy tiếp"], "a": 1, "e": "terminate dừng chương trình ngay (Aborted), in tên kiểu và what()."}]);

